import { mountSpider } from "./three-bridge/spider.scene";

declare global {
  interface Window {
    __EVAL_READY__?: boolean;
    __TASK_STATE__?: { walking: boolean };
  }
}

const app = mountSpider("#app");
const state = { walking: true };
window.__TASK_STATE__ = state;

const setWalking = (walking: boolean): void => {
  state.walking = walking;
  window.__TASK_STATE__ = { walking };
  const spider = app.nodes.has("spider") ? app.nodes.require("spider") : undefined;
  if (spider) spider.timeScale = walking ? 1 : 0;
};

window.addEventListener("keydown", (event) => {
  if (event.code !== "Space" && event.key !== " ") return;
  event.preventDefault();
  if (event.repeat) return;
  setWalking(!state.walking);
});

// TEMP DEBUG
const dbg = document.createElement("div");
dbg.style.cssText = "position:fixed;left:0;top:0;color:#000;background:#fff;font:12px monospace;z-index:9";
document.body.appendChild(dbg);
let marked = false;
app.onFrame((f) => {
  if (!marked) {
    marked = true;
    requestAnimationFrame(() => {
      window.__EVAL_READY__ = true;
    });
  }
  if (f.time > 1 && state.walking && f.time < 1.1) setWalking(false);
  const spider = app.nodes.has("spider") ? app.nodes.require("spider") : undefined;
  const st = spider?.animation?.animationState();
  dbg.textContent = `walking=${state.walking} time=${f.time.toFixed(2)} anim=${JSON.stringify(st?.activeActions)} ts=${st?.timeScale}`;
});
void app.ready();

